{
    "predictors": [
        {
            "name": "R&D Intensity",
            "construction": "Total R&D expenditure divided by total sales, calculated annually from firm financial statements.",
            "rationale": "Firms investing heavily in R&D may have higher growth potential and innovation capabilities, leading to higher future returns.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Employee Growth Rate",
            "construction": "Annual percentage change in the number of employees, sourced from company reports.",
            "rationale": "Rapidly growing firms in terms of workforce may be expanding operations and capturing market share, potentially leading to higher future returns.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Insider Trading Volume",
            "construction": "Total volume of insider purchases minus insider sales over the past year, as reported to the SEC.",
            "rationale": "Insiders may have superior information about firm prospects; net buying could signal confidence in future performance.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Supplier Concentration",
            "construction": "Percentage of total purchases from the top three suppliers, calculated annually from firm disclosures.",
            "rationale": "Firms with less concentrated suppliers may have better bargaining power and supply chain stability, potentially enhancing profitability.",
            "higher_returns_for": "low values of the measure"
        },
        {
            "name": "Patent Count Growth",
            "construction": "Annual percentage change in the number of patents granted, sourced from patent office records.",
            "rationale": "An increasing number of patents may indicate a firm's innovative capacity and potential for future growth.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Environmental Compliance Score",
            "construction": "Score based on compliance with environmental regulations, derived from EPA reports and firm disclosures.",
            "rationale": "Firms with better environmental compliance may face fewer regulatory risks and enjoy a better public image, potentially leading to higher returns.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Customer Satisfaction Index",
            "construction": "Annual customer satisfaction score from industry surveys and reports.",
            "rationale": "Higher customer satisfaction can lead to repeat business and brand loyalty, potentially enhancing future profitability.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Foreign Revenue Exposure",
            "construction": "Percentage of total revenue derived from foreign markets, calculated annually from firm financial statements.",
            "rationale": "Firms with higher foreign revenue exposure may benefit from international growth opportunities and diversification.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Dividend Consistency",
            "construction": "Standard deviation of dividend payments over the past five years, calculated from firm financial statements.",
            "rationale": "Consistent dividend payments may signal financial stability and management's confidence in future cash flows.",
            "higher_returns_for": "low values of the measure"
        },
        {
            "name": "Advertising Intensity",
            "construction": "Total advertising expenditure divided by total sales, calculated annually from firm financial statements.",
            "rationale": "Firms with higher advertising intensity may be investing in brand equity and market share expansion, potentially leading to higher future returns.",
            "higher_returns_for": "high values of the measure"
        }
    ]
}
